package com.bank.reference;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TrieDemo {

    private static final Logger log = Logger.getLogger(TrieDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ReferenceCodeTrie trie = new ReferenceCodeTrie();

        trie.insert("SAV");
        trie.insert("SAV2001");
        trie.insert("CUR3001");

        log.info(() -> "search 'SAV2001' = " + trie.search("SAV2001")); // true
        log.info(() -> "search 'SAV2' = " + trie.search("SAV2"));       // false (prefix only)
        log.info(() -> "startsWith 'SAV' = " + trie.startsWith("SAV")); // true
        log.info(() -> "startsWith 'LOAN' = " + trie.startsWith("LOAN"));// false
    }
}

