class TrieNode {
    final java.util.Map<Character, TrieNode> children = new java.util.HashMap<>();
    boolean isWord = false;   // marks a complete code ending here
}

// ─── Would be in service/ReferenceCodeTrie.java in a real project ───
class ReferenceCodeTrie {

    private static final Logger log = Logger.getLogger(ReferenceCodeTrie.class.getName());

    private final TrieNode root = new TrieNode();

    void insert(String word) {
        TrieNode node = root;
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            node = node.children.computeIfAbsent(c, x -> new TrieNode());
        }
        node.isWord = true;                // end flag for a full code
        log.fine(() -> "  inserted " + word);
    }

    boolean search(String word) {
        TrieNode node = walk(word);
        return node != null && node.isWord; // path AND end flag
    }

    boolean startsWith(String prefix) {
        return walk(prefix) != null;        // path only
    }

    // Follow the characters; return the final node or null if the path breaks.
    private TrieNode walk(String s) {
        TrieNode node = root;
        for (int i = 0; i < s.length(); i++) {
            node = node.children.get(s.charAt(i));
            if (node == null) return null;
        }
        return node;
    }
}

